fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let mut a = a;
    // Split index; for n>1 this is in [1..n), for n<=1 it's 0.
    let mid = a.len() / 2;
    // Takes everything from a[mid..] and returns it as a new Vec,
    // truncating `a` to a[..mid].
    let second = a.split_off(mid);
    // Now `a` is the first half, `second` is the second half.
    (a, second)
}

